post_connection:
async function(n,id){
const p=load("connection_plan")[n-1],t="tab_b_6c89121c-a089-4904-bb83-a33efbd6ad7f";
if(p.connections?.some(x=>x.problem_id===id))throw Error("Already connected; skip duplicate");
await tools.mcp__t3_code__preview_open({tabId:t,url:"https://mathdb.com/p/"+id,open:false});
let before=await tools.mcp__t3_code__preview_evaluate({tabId:t,expression:"new Promise(resolve=>{const read=()=>({url:location.href,canonical:document.querySelector('link[rel=canonical]')?.href,title:document.querySelector('main h1')?.innerText,text:document.querySelector('main')?.innerText,solutions:[...document.querySelectorAll('section.solution')].map(e=>({id:e.id,text:e.textContent,links:[...e.querySelectorAll('a[href]')].map(a=>a.href)}))});const done=()=>{if(document.querySelector('main h1')&&document.querySelector('.solutions__composer button')){obs.disconnect();resolve(read());return true;}return false;};const obs=new MutationObserver(done);obs.observe(document.documentElement,{subtree:true,childList:true});if(!done())setTimeout(()=>{obs.disconnect();resolve(read());},10000);})"});
const v=before.structuredContent?.value;if(!v?.title)throw Error("Problem did not load "+JSON.stringify(before));
if(v.solutions.some(x=>x.links.includes(p.paper_url)||x.links.some(l=>l.includes(p.doi))))throw Error("Existing solution already links paper, inspect before duplicate");
let b64=eval("("+load("b64function")+")");
let save=await tools.exec_command({cmd:"python3 - <<'PY'\nimport pathlib,base64\np=pathlib.Path('openai-proof-research/output/submissions/2026-10-27-new-discoveries/problem-source-before');p.mkdir(exist_ok=True);(p/"+JSON.stringify(String(id)+".json")+").write_bytes(base64.b64decode('"+b64(JSON.stringify(v))+"'))\nPY","max_output_tokens":100});if(save.exit_code!==0)throw Error(save.output);
await tools.mcp__t3_code__preview_snapshot({tabId:t}); let opened=false;for(let j=0;j<3;j++){let d=await tools.mcp__t3_code__preview_evaluate({tabId:t,expression:"!!document.querySelector('.solution-compose-dialog')"});if(d.structuredContent?.value){opened=true;break;}await tools.mcp__t3_code__preview_act({tabId:t,action:"click",selector:".solutions__composer button"});} if(!opened){let d=await tools.mcp__t3_code__preview_evaluate({tabId:t,expression:"!!document.querySelector('.solution-compose-dialog')"});if(!d.structuredContent?.value)throw Error("Composer did not open");}for(const a of [{action:"type",selector:'textarea[aria-label="Summary"]',text:p.summary,clear:true},{action:"type",selector:'textarea[placeholder="Write your solution…"]',text:p.body,clear:true},{action:"select",selector:'select[aria-label="Label"]',values:[p.label]}]){const r=await tools.mcp__t3_code__preview_act({tabId:t,...a});if(r.isError)throw Error(JSON.stringify(r));}
let vr=await tools.mcp__t3_code__preview_evaluate({tabId:t,expression:"({summary:document.querySelector('textarea[aria-label=Summary]').value,body:document.querySelector('textarea[placeholder=\"Write your solution…\"]').value,label:document.querySelector('select[aria-label=Label]').value})"});let f=vr.structuredContent?.value;if(!f||f.summary!==p.summary||f.body!==p.body||f.label!==p.label)throw Error("Composer mismatch");
let click=await tools.mcp__t3_code__preview_act({tabId:t,action:"click",selector:'.solution-compose-dialog button[type="submit"]'});if(click.isError)throw Error("Posting may have happened; inspect "+JSON.stringify(click));
let after=await tools.mcp__t3_code__preview_evaluate({tabId:t,expression:"new Promise(resolve=>{const paper="+JSON.stringify(p.paper_url)+";const read=()=>({url:location.href,title:document.querySelector('main h1')?.innerText,solutions:[...document.querySelectorAll('section.solution')].map(e=>({id:e.id,text:e.textContent,links:[...e.querySelectorAll('a[href]')].map(a=>a.href)})),dialog:document.querySelector('.solution-compose-dialog')?.innerText});const done=()=>{let x=read();if(x.solutions.some(e=>e.links.includes(paper))||(x.dialog?.includes('too often')||x.dialog?.includes('429'))){obs.disconnect();resolve(x);return true;}return false;};const obs=new MutationObserver(done);obs.observe(document.documentElement,{subtree:true,childList:true});if(!done())setTimeout(()=>{obs.disconnect();resolve(read());},12000);})"});
const w=after.structuredContent?.value;let match=w?.solutions?.find(x=>x.links.includes(p.paper_url)&&x.links.includes("https://doi.org/"+p.doi));if(!match)throw Error("Post unverified, retain form and inspect "+JSON.stringify(after));
let event={problem_id:id,url:w.url+"#"+match.id,kind:"solution",label:p.label,paper_url:p.paper_url,doi:p.doi,verified:true,problem_title:w.title,evidence:match};
text(await tools.exec_command({cmd:"python3 openai-proof-research/output/submissions/2026-10-27-new-discoveries/record_connection.py "+n+" "+b64(JSON.stringify(event)),max_output_tokens:250}));
text({n,problem:id,title:w.title,label:p.label,url:event.url});return event;
}

create_problem:
async function(n){
const p=load("connection_plan")[n-1],d=p.new_problem_draft,t="tab_c_6c89121c-a089-4904-bb83-a33efbd6ad7f";if(!d||p.created_problem)throw Error("No new draft or already created");
await tools.mcp__t3_code__preview_open({tabId:t,url:"https://mathdb.com/new",open:false});
let wait=await tools.mcp__t3_code__preview_wait_for({tabId:t,selector:"#ask-title",timeoutMs:10000});if(wait.isError)throw Error(JSON.stringify(wait));
for(const [selector,txt]of [["#ask-title",d.title],['textarea[placeholder="Write the problem statement…"]',d.body],["#ask-references",d.reference]]){const a=await tools.mcp__t3_code__preview_act({tabId:t,action:"type",selector,text:txt,clear:true});if(a.isError)throw Error(JSON.stringify(a));}
const r=await tools.mcp__t3_code__preview_evaluate({tabId:t,expression:"({title:document.querySelector('#ask-title').value,body:document.querySelector('textarea[placeholder=\"Write the problem statement…\"]').value,ref:document.querySelector('#ask-references').value})"});const v=r.structuredContent?.value;if(v?.title!==d.title||v.body!==d.body||v.ref!==d.reference)throw Error("Problem draft UI mismatch");
const ss=await tools.mcp__t3_code__preview_snapshot({tabId:t});const rf=ss.structuredContent?.accessibilityTree?.split('button "Post problem"')[1]?.split('[ref=')[1]?.split(']')[0];if(!rf)throw Error("No problem submit locator");const click=await tools.mcp__t3_code__preview_act({tabId:t,action:"click",locator:"aria-ref="+rf});if(click.isError)throw Error("Creation may have occurred; inspect "+JSON.stringify(click));
let a;for(let k=0;k<3;k++){a=await tools.mcp__t3_code__preview_evaluate({tabId:t,expression:"new Promise(resolve=>{const read=()=>({url:location.href,title:document.querySelector('main h1')?.innerText,text:document.querySelector('main')?.innerText});const done=()=>{if(location.pathname.startsWith('/p/')&&document.querySelector('main h1')?.innerText!=='Post a problem'){o.disconnect();resolve(read());return true;}return false;};const o=new MutationObserver(done);o.observe(document.documentElement,{childList:true,subtree:true});if(!done())setTimeout(()=>{o.disconnect();resolve(read());},10000);})"});if(a.structuredContent?.value?.url?.includes('/p/'))break;}
const w=a.structuredContent?.value;if(!w?.url?.includes("/p/")||w.title!==d.title)throw Error("Creation not verified "+JSON.stringify(a));const b64=eval("("+load("b64function")+")");
text(await tools.exec_command({cmd:"python3 openai-proof-research/output/submissions/2026-10-27-new-discoveries/record_new_problem.py "+n+" "+b64(JSON.stringify({url:w.url,title:w.title,evidence:w,source_scope:d.body,answer_paper:p.paper_url})),max_output_tokens:300}));text({n,new_problem:w.url});return w;
}

